// Lesson frames pilot (EDD-003 stage 1): the manifest's rules, hashes and the artifact origin's headers, in one place.
// Used by tools/lesson-frames.mjs (build, check, prune, serve, check-origin) and by the gate suite tests/lesson-frames.
// Spec: company/engineering/reviews/2026-10-25-content-hub-production-review.md (C1, C4; ADR-004, ADR-007).
//
// Files (all generated by `node tools/lesson-frames.mjs build`, all committed; every change is a git commit, ADR-007):
//   src/lib/lesson-frames.manifest.json  the record: origin, toolchain, kit, and per slug sourceHash + artifact hashes
//   src/lib/lesson-frames.slugs.json     client: the framed slugs (DemoHost, flag on only)
//   src/lib/lesson-frames.frames.json    client: origin + slug → frameDoc (DemoFrame, flag on only)
// The two client files are exact projections of the manifest, so the record's source lists never reach a browser.

import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
export const MANIFEST = "src/lib/lesson-frames.manifest.json";
export const CLIENT_SLUGS = "src/lib/lesson-frames.slugs.json";
export const CLIENT_FRAMES = "src/lib/lesson-frames.frames.json";
export const PILOT_SLUGS_FILE = "company/engineering/edd/EDD-003-a2-pilot-slugs.txt";
export const SCHEMA = 1;
/** The one origin a committed manifest may name (review: the existing separate project; vercel.app is on the PSL). */
export const ALLOWED_ORIGIN = "https://system3-content-hub-artifacts.vercel.app";
/** Production host that may embed frames. A preview alias is added per deploy with --frame-ancestors (release-manager). */
export const PRODUCTION_HOST = "https://system-3-company.vercel.app";
export const HEX64 = /^[0-9a-f]{64}$/;

export const sha256 = (b) => crypto.createHash("sha256").update(b).digest("hex");

/** Pilot slugs, in file order (comments and the '# cp' marks stripped). */
export function pilotSlugs(root = ROOT) {
  return fs
    .readFileSync(path.join(root, PILOT_SLUGS_FILE), "utf8")
    .split("\n")
    .map((l) => l.replace(/#.*$/, "").trim())
    .filter(Boolean);
}

export function findLessonDir(slug, root = ROOT) {
  const demos = path.join(root, "src/demos");
  for (const d of fs.readdirSync(demos)) {
    const dir = path.join(demos, d, slug);
    if (fs.existsSync(path.join(dir, "Demo.tsx"))) return path.relative(root, dir);
  }
  return null;
}

export function lessonStatus(slug, root = ROOT) {
  const dir = findLessonDir(slug, root);
  if (!dir) return null;
  return JSON.parse(fs.readFileSync(path.join(root, dir, "meta.json"), "utf8")).status;
}

/**
 * The hash of a canonical source tree (ADR-004): sorted repo-relative paths, each with the sha256 of its bytes.
 * A file that no longer exists hashes as "missing", so a deleted source makes the tree stale too.
 */
export function treeHash(files, root = ROOT) {
  const lines = [...new Set(files)].sort().map((f) => {
    const p = path.join(root, f);
    return `${f}\0${fs.existsSync(p) ? sha256(fs.readFileSync(p)) : "missing"}`;
  });
  return sha256(lines.join("\n"));
}

/** A lesson's canonical tree: the files its bundle was compiled from, plus its meta.json (status and claims). */
export function lessonSources(slug, compiled, root = ROOT) {
  const dir = findLessonDir(slug, root);
  return [...new Set([...compiled.filter(isSource), `${dir}/meta.json`])].sort();
}
/** Source, not toolchain: webpack also reports package.json and the spike/tooling loaders, which toolchain() records. */
const isSource = (f) => f.startsWith("src/") || f.startsWith("spike/kit/");

export function toolchain(root = ROOT) {
  const tooling = fs
    .readdirSync(path.join(root, "spike/tooling"))
    .sort()
    .map((f) => `spike/tooling/${f}`);
  return {
    buildMjs: sha256(fs.readFileSync(path.join(root, "spike/build.mjs"))),
    tooling: treeHash(tooling, root),
    packageLock: sha256(fs.readFileSync(path.join(root, "package-lock.json"))),
    next: JSON.parse(fs.readFileSync(path.join(root, "node_modules/next/package.json"), "utf8")).version,
  };
}

const hashOf = (url) => url.match(/([0-9a-f]{64})\.(js|css|html)$/)?.[1] ?? null;

/** Build the manifest record from spike/build.mjs results. */
export function manifestFrom({ kit, lessons, origin, root = ROOT }) {
  const m = {
    schema: SCHEMA,
    kitVersion: kit.version,
    origin,
    toolchain: toolchain(root),
    kit: {
      js: hashOf(kit.js.url),
      css: hashOf(kit.css.url),
      boot: hashOf(kit.boot.url),
      geo: hashOf(kit.geo.url),
      sourceHash: treeHash(kit.sources.filter(isSource), root),
      sources: kit.sources.filter(isSource),
      geoSourceHash: treeHash(kit.geoSources.filter(isSource), root),
      geoSources: kit.geoSources.filter(isSource),
    },
    lessons: {},
  };
  for (const r of lessons) {
    const sources = lessonSources(r.slug, r.sources, root);
    m.lessons[r.slug] = {
      sourceHash: treeHash(sources, root),
      sources,
      lessonJs: r.hash,
      kit: m.kit.js,
      kitCss: m.kit.css,
      geoKit: r.geo ? m.kit.geo : null,
      frameDoc: r.frameHash,
    };
  }
  return m;
}

export const clientSlugs = (m) => ({ note: "generated by tools/lesson-frames.mjs from src/lib/lesson-frames.manifest.json; do not edit", slugs: Object.keys(m.lessons) });
export const clientFrames = (m) => ({
  note: "generated by tools/lesson-frames.mjs from src/lib/lesson-frames.manifest.json; do not edit",
  origin: m.origin,
  frames: Object.fromEntries(Object.entries(m.lessons).map(([s, e]) => [s, e.frameDoc])),
});

export function writeManifest(m, root = ROOT) {
  const w = (rel, v) => fs.writeFileSync(path.join(root, rel), JSON.stringify(v, null, 2) + "\n");
  w(MANIFEST, m);
  w(CLIENT_SLUGS, clientSlugs(m));
  w(CLIENT_FRAMES, clientFrames(m));
}

export function readManifest(root = ROOT) {
  return JSON.parse(fs.readFileSync(path.join(root, MANIFEST), "utf8"));
}

/**
 * Every rule a committed manifest must meet (the gate suite asserts problems(...) is empty).
 * Each problem: { slug|null, rule, detail }.
 */
export function problems(m, { root = ROOT, allowedOrigin = ALLOWED_ORIGIN } = {}) {
  const out = [];
  const p = (slug, rule, detail) => out.push({ slug, rule, detail });
  if (m.schema !== SCHEMA) p(null, "schema", `schema ${m.schema}, expected ${SCHEMA}`);
  if (m.origin !== allowedOrigin) p(null, "origin", `origin ${m.origin} is not the allow-listed ${allowedOrigin}`);
  for (const k of ["js", "css", "boot", "geo", "sourceHash", "geoSourceHash"]) if (!HEX64.test(m.kit?.[k] ?? "")) p(null, "hash", `kit.${k} is not 64-hex`);
  for (const k of ["buildMjs", "tooling", "packageLock"]) if (!HEX64.test(m.toolchain?.[k] ?? "")) p(null, "hash", `toolchain.${k} is not 64-hex`);
  // A stale kit matters only while an entry still uses it: prune drops those entries, and an unused kit serves nothing (W-2105).
  const entries = Object.values(m.lessons ?? {});
  if (m.kit && entries.length && treeHash(m.kit.sources ?? [], root) !== m.kit.sourceHash) p(null, "stale-kit", "the kit's sources changed since its artifact was built: rebuild (node tools/lesson-frames.mjs build) or drop its entries (node tools/lesson-frames.mjs prune)");
  if (m.kit && entries.some((e) => e.geoKit !== null) && treeHash(m.kit.geoSources ?? [], root) !== m.kit.geoSourceHash) p(null, "stale-kit", "the geo kit's sources changed since its artifact was built: rebuild, or drop the entries that use it (prune)");
  const pilot = new Set(pilotSlugs(root));
  const loaders = fs.readFileSync(path.join(root, "src/demos/loaders.generated.ts"), "utf8");
  for (const [slug, e] of Object.entries(m.lessons ?? {})) {
    if (!pilot.has(slug)) p(slug, "pilot", `not in ${PILOT_SLUGS_FILE}`);
    if (!loaders.includes(`"${slug}":`)) p(slug, "fallback", "not in src/demos/loaders.generated.ts, so it cannot fall back in-app");
    const status = lessonStatus(slug, root);
    if (status !== "published") p(slug, "published", `status is ${status ?? "missing"}`);
    for (const k of ["sourceHash", "lessonJs", "kit", "kitCss", "frameDoc"]) if (!HEX64.test(e[k] ?? "")) p(slug, "hash", `${k} is not 64-hex`);
    if (e.geoKit !== null && !HEX64.test(e.geoKit ?? "")) p(slug, "hash", "geoKit is neither null nor 64-hex");
    if (e.kit !== m.kit?.js || e.kitCss !== m.kit?.css || (e.geoKit !== null && e.geoKit !== m.kit?.geo)) p(slug, "kit", "names a kit other than the manifest's");
    if (treeHash(e.sources ?? [], root) !== e.sourceHash) p(slug, "stale", "source changed since its artifact was built: rebuild, or drop it (node tools/lesson-frames.mjs prune)");
  }
  const read = (rel) => (fs.existsSync(path.join(root, rel)) ? JSON.parse(fs.readFileSync(path.join(root, rel), "utf8")) : null);
  if (JSON.stringify(read(CLIENT_SLUGS)) !== JSON.stringify(clientSlugs(m))) p(null, "client", `${CLIENT_SLUGS} is not the manifest's projection: re-run the tool`);
  if (JSON.stringify(read(CLIENT_FRAMES)) !== JSON.stringify(clientFrames(m))) p(null, "client", `${CLIENT_FRAMES} is not the manifest's projection: re-run the tool`);
  return out;
}

/**
 * What prune drops (W-2105): entries that are stale or not published, not in the pilot list, or without an in-app
 * fallback; with a stale kit, every entry (each one names it); with a stale geo kit, every entry that uses it. Dropping,
 * not rebuilding: a dropped lesson renders in-app, and a rebuild needs an artifact deploy (release-manager's) before
 * its frames serve. Rebuild with `node tools/lesson-frames.mjs build`. Pure: returns the pruned copy and the reasons.
 */
export function pruneManifest(m, { root = ROOT } = {}) {
  const x = structuredClone(m);
  const ps = problems(m, { root });
  const why = new Map();
  const add = (slug, rule) => why.set(slug, [...(why.get(slug) ?? []), rule]);
  for (const p of ps) if (p.slug && ["stale", "published", "pilot", "fallback"].includes(p.rule)) add(p.slug, p.rule);
  const kitStale = !!m.kit && treeHash(m.kit.sources ?? [], root) !== m.kit.sourceHash;
  const geoStale = !!m.kit && treeHash(m.kit.geoSources ?? [], root) !== m.kit.geoSourceHash;
  for (const [slug, e] of Object.entries(m.lessons ?? {})) {
    if (kitStale) add(slug, "stale-kit");
    else if (geoStale && e.geoKit !== null) add(slug, "stale-kit (geo)");
  }
  for (const s of why.keys()) delete x.lessons[s];
  return { manifest: x, dropped: [...why].map(([slug, rules]) => ({ slug, rules })), kitStale, geoStale };
}

// ---------------------------------------------------------------- which problems block (O1, W-2104)

/** The flag value that turns frames on (src/components/DemoHost.tsx, next.config.mjs). Anything else is off. */
export const FLAG_ON = "pilot-50";
export const framesOn = (env = process.env) => env.NEXT_PUBLIC_LESSON_FRAMES === FLAG_ON;

/**
 * Freshness rules: they compare the manifest with today's lesson and kit sources, which change every week. With the
 * flag off no client chunk holds the manifest or DemoFrame (P4), so a stale entry serves nothing, and these rules must
 * not block a flag-off deploy. With the flag on they block, at the build itself (next.config.mjs), because only the
 * build knows the flag value the deployed app gets: a --prebuilt deploy builds with the pulled Vercel environment, and
 * a [deploy] commit builds on Vercel without running npm run verify.
 * Every other rule (schema, origin, hashes, pilot list, kit names, projections) is structural, changes only when the
 * manifest is regenerated, and blocks always.
 * Ruling: company/decisions/2026-10-26-lesson-frames-gate-scope.md.
 */
export const FRESHNESS_RULES = new Set(["stale", "stale-kit", "published", "fallback"]);

/** The problems that block, given whether the build turns frames on. */
export function blocking(ps, { on = framesOn() } = {}) {
  return on ? ps : ps.filter((p) => !FRESHNESS_RULES.has(p.rule));
}

/** For next.config.mjs: with the flag on, any problem fails the build. Returns the message, or null. */
export function flagOnBuildRefusal({ env = process.env, root = ROOT } = {}) {
  if (!framesOn(env)) return null;
  const ps = problems(readManifest(root), { root });
  if (ps.length === 0) return null;
  return [
    `NEXT_PUBLIC_LESSON_FRAMES=${FLAG_ON}, but the lesson frames manifest has ${ps.length} problem(s):`,
    ...ps.map((p) => `  ${p.slug ?? "(manifest)"}: ${p.rule}: ${p.detail}`),
    "Fix: node tools/lesson-frames.mjs prune (the lesson renders in-app) or a rebuild, then commit; or build with the flag off.",
  ].join("\n");
}

// ---------------------------------------------------------------- the artifact origin's headers (C4)

/**
 * One rule per path class. The frame documents' header CSP is generic; each frame's own meta CSP pins its import map
 * by hash, and browsers enforce both: a script runs only if each policy allows it. The header allows inline scripts,
 * the meta policy allows only the hashed import map, so only that import map runs. Without 'unsafe-inline' the
 * header would block the import map, which is an inline script, and no frame would run.
 */
export function frameCsp(frameAncestors) {
  return [
    "default-src 'none'",
    "script-src 'self' 'unsafe-inline'",
    "style-src 'self'",
    "img-src 'self' data:",
    "font-src 'self'",
    "connect-src 'none'",
    "base-uri 'none'",
    "form-action 'none'",
    `frame-ancestors ${frameAncestors.join(" ")}`,
    "sandbox allow-scripts",
  ].join("; ");
}

const IMMUTABLE = "public, max-age=31536000, immutable";
const STATIC = [
  { key: "Cache-Control", value: IMMUTABLE },
  { key: "X-Content-Type-Options", value: "nosniff" },
  { key: "Access-Control-Allow-Origin", value: "*" }, // module fetches from an opaque-origin frame are CORS, never credentialed
  { key: "Cross-Origin-Resource-Policy", value: "cross-origin" },
];

export function headerRules(frameAncestors = [PRODUCTION_HOST]) {
  for (const a of frameAncestors) if (!/^https?:\/\/[a-z0-9.-]+(:\d+)?$/.test(a)) throw new Error(`frame ancestor ${a} is not an origin`);
  return [
    { source: "/kit/(.*)", headers: STATIC },
    { source: "/kit-geo/(.*)", headers: STATIC },
    { source: "/l/(.*)", headers: STATIC },
    {
      source: "/f/(.*)",
      headers: [
        { key: "Cache-Control", value: IMMUTABLE },
        { key: "X-Content-Type-Options", value: "nosniff" },
        { key: "Referrer-Policy", value: "no-referrer" },
        { key: "Content-Security-Policy", value: frameCsp(frameAncestors) },
      ],
    },
  ];
}

/** The artifact project's vercel.json (static, no build). Written beside the artifacts; release-manager deploys it. */
export const originVercelJson = (frameAncestors) => ({ $schema: "https://openapi.vercel.sh/vercel.json", framework: null, cleanUrls: false, headers: headerRules(frameAncestors) });

/** Headers for one request path, from the same rules (the local origin server uses this). */
export function headersFor(pathname, frameAncestors) {
  for (const r of headerRules(frameAncestors)) {
    const prefix = r.source.replace("(.*)", "");
    if (pathname.startsWith(prefix)) return Object.fromEntries(r.headers.map((h) => [h.key, h.value]));
  }
  return null;
}
